import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"中孚","description":"东坡易传 - 中孚","frontmatter":{"title":"中孚","description":"东坡易传 - 中孚"},"headers":[],"relativePath":"zh/classics/dongpo/062.md","filePath":"zh/classics/dongpo/062.md"}'),o={name:"zh/classics/dongpo/062.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="中孚" tabindex="-1">中孚 <a class="header-anchor" href="#中孚" aria-label="Permalink to “中孚”">​</a></h1><p>“中孚”，豚魚，吉。利涉大川，利貞。</p><p>《彖》曰：“中孚”，柔在內而剛得中，說而“巽”，孚乃化邦也。 “豚魚，吉”，信及豚魚也。 “利涉大川”，乘木舟虛也。 “中孚”以“利貞”，乃應乎天也【天道不容僞】。</p><p>“中孚”，信也。而謂之“中孚”者，如羽蟲之孚，有諸中而後能化也。羽蟲之孚也，必柔內而剛外，然則“頤”曷爲不“中孚”也？曰：內無陽不生，故必柔內而剛外，且剛得中，然後爲“中孚”也。剛得中則正，而一柔在內，則靜而久，此羽蟲之所以孚天之道也。君子法之，行之以“說”，輔之以“巽”，而民化矣。</p><p>信之及民，容有僞；其及豚魚，不容有僞也。至於豚魚皆吉，則其信也至矣。</p><p>《易》至於“巽”在上而云“涉川”者，其言必及木。“益”之《彖》曰：“木道乃行。”“渙”之《彖》曰：“乘木有功。”“中孚”之《彖》曰“乘木舟虛”，以明此“巽”之功也。以“巽”行“兌”，乘天下之至順而行於人之所說，必無心者也。“舟虛”者，無心之謂也。</p><p>象曰：澤上有風，“中孚”，君子以議獄緩死。</p><p>化邦之時，不可以用刑。</p><p>初九：虞，吉；有它不燕。象曰：“初九虞吉”，志未變也。</p><p>“虞”，戒也，燕安也。六四，初九之應也；而近於五，爲五所攣。所謂“它”也，六四不專於應，而有心於五，其色不安，此必變者也。初九及其未變，而戒之不輕往應，則遠於爭矣，故“吉”。</p><p>九二：鶴鳴在陰，其子和之；我有好爵，吾與爾靡之。象曰：“其子和之”，中心原也。</p><p>此“中孚”也，而爻未有能“中孚”者也。“中孚”者必正而一、靜而久，而初九、六四，六三、上九有應而相求，九五無應而求人者也，皆非所謂正而一、靜而久者也。惟九二以剛履柔，伏於二陰之下，端欲無求而物自應焉，故曰：“鳴鶴在陰，其子和之。”鶴鳴而子和者，天也；未有能使之者也。“我有好爵，吾與爾靡之”，有爵者，求我之辭也；彼求我、而我不求之之謂也。</p><p>六三：得敵，或鼓或罷，或泣或歌。象曰：“或鼓或罷”，位不當也。</p><p>六三履非其位，雖應在上九，而上九非下我者也。上不求三而三求之，求之必過五，五無應而寇我，故曰“得敵”也。得敵而躁，躁而失常，故“或鼓或罷，或泣或歌”也。</p><p>六四：月幾望，馬匹亡，無咎。象曰：“馬匹亡”，絕類上也。</p><p>初九以應而從我，九五以近而攣我，一陰而當二陽之求，盛之至也。故曰“月幾望”。“月幾望”者，非四之所任也，故必舍五而從初。如有二馬而亡其一，然後“無咎”，類五也。四與五皆“巽”也，故得稱“類”。</p><p>九五：有孚，攣如；無咎。象曰：“有孚攣如”，位正當也。</p><p>“有孚”者，六四也。自五言之，則以得四爲“無咎”，非應而求，從必攣而後固。特以其位當，是以“無咎”也。</p><p>上九：翰音，登於天；貞兇。象曰：“翰音登於天”，何可長也！</p><p>“翰音”，飛且鳴者也。凡羽蟲之飛且鳴者，其飛不長，雉雞之類是也。處外而居上，非“中孚”之道；飛而求顯、鳴而求信者也，故曰：“翰音，登於天”。九二在陰而子和，上九飛鳴而登天，其道蓋相反也；惟不下從陰得陽之正，故曰“貞兇”。</p>',20)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
